import {hearButton} from './play-media.mjs';
import {walkCases,walkTime} from './courier-clock-content.mjs';
import {clockWalkView,walkText,parseWalkMinutes,startClockWalk,editClockWalk,supportClockWalk,checkClockWalk,keepClockWalk,recoverClockWalk} from './courier-clock-core.mjs';
import {walkClock,walkTimeline} from './courier-clock-art.mjs';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const btn=(label,attrs,primary=false)=>`<button type="button" class="${primary?'primary':'secondary'}" ${attrs}>${esc(label)}</button>`;
const names={learn:'Learn',walk:'Walk',kept:'Kept'},pages=Object.keys(names),label=w=>walkTime((w.source.departureMinute+w.offset)%720);
const reference=s=>`<aside class="cw-reference"><p><strong>Departure ${esc(s.departureLabel)}</strong> · Requested arrival <strong>${esc(s.arrivalLabel)}</strong></p></aside>`;
const answer=w=>w.durationMode==='unsure'?'Not sure':w.durationInput.trim()===''?'Blank':w.durationInput;
const endpoint=w=>w.endpointChoice==='clock'?'Our model is proposed as arrival':w.endpointChoice==='unsure'?'Not sure about arrival':'No arrival proposal yet';
function currentFigure(w){return `<figure class="cw-figure"><figcaption>Our model · ${esc(label(w))}</figcaption>${walkClock((w.source.departureMinute+w.offset)%720)}<p class="tiny">Short hand: hour · Long hand: minute</p></figure>${walkTimeline(w.offset)}`;}
function example(w,step){const e=w.source.example,o=e.offsets[step],m=(e.departureMinute+o)%720;return `<figure class="cw-figure"><figcaption>Supplied example · ${walkTime(e.departureMinute)} to ${walkTime((e.departureMinute+e.offsets[2])%720)}</figcaption>${walkClock(m,'Supplied example clock')}</figure>${walkTimeline(o,step===0?[]:step===1?[[0,o]]:[[0,e.offsets[1]],[e.offsets[1],o]])}<p data-cw-example-caption>${esc(e.captions[step])}</p>`;}
function chooser(v){return `<details class="cw-chooser" ${v.work?'':'open'}><summary>Choose any clock card</summary>${walkCases.map(s=>{const c=v.readable.find(c=>c.id===s.id),bad=v.unreadable.some(c=>c.id===s.id);return `<article><h3>${esc(c?.work.source.title||s.title)}</h3>${bad?'<p>An earlier unreadable card stays in your download; other cards remain open.</p>':btn(c?'Resume this card':'Start this card',`data-cw-start="${s.id}"`)}</article>`;}).join('')}${v.readable.filter(c=>!walkCases.some(s=>s.id===c.id)).map(c=>`<article><h3>${esc(c.work.source.title)}</h3>${btn('Resume earlier card',`data-cw-start="${esc(c.id)}"`)}</article>`).join('')}</details>`;}
function checkRecord(c,current=false){return `<article class="cw-check" data-cw-record="${c.id}" ${current?`data-cw-current id="cw-check-${c.id}"`:''} tabindex="-1"><h3>${current?'Check of this version':'Earlier recorded check'} ${c.id}</h3><p>${esc(c.feedback)}</p>${hearButton(c.feedback,'Hear this recorded check')}<details><summary>Inputs and support in this check</summary><p>Arrival: ${esc(endpoint(c.snapshot))}. Minutes: ${esc(answer(c.snapshot))}. Support: ${esc(c.snapshot.support.join(', ')||'none requested')}.</p><p>Supplied model practice; prior exposure is unknown.</p></details></article>`;}
function narration(v){if(!v.work)return 'Choose any clock card. All six cards are open.';const w=v.work;if(w.page==='kept')return v.kept?walkText(v.kept.snapshot.source.copy.reference,v.kept.snapshot)+' '+walkText(v.kept.snapshot.source.copy.model,v.kept.snapshot)+' Minutes: '+answer(v.kept.snapshot)+'. '+(v.kept.check?.feedback||'Kept without a check.'):v.keptUnreadable?'An earlier kept version stays unreadable in your notes.':'Nothing kept yet.';return w.page==='learn'?w.source.copy.idea+' '+w.source.copy.scale+' '+walkText(w.source.copy.reference,w):w.source.copy.instruction+' '+walkText(w.source.copy.reference,w)+' '+walkText(w.source.copy.model,w)+' '+endpoint(w)+'. Proposed minutes: '+answer(w)+'.';}
export const clockWalkEntry=()=>'<section class="resume-strip"><div><h2>Courier Clock Walk</h2><p>Keep departure fixed. Discover the minutes between two times.</p><a class="secondary" href="#post/clock-walk">Try a clock walk</a></div></section>';
export function clockWalkPage(state){
 const v=clockWalkView(state),head='<section class="cw-sheet" data-cw-root><a class="back" href="#post">Back to Post Office</a>',status='<p id="cw-status" role="status" tabindex="-1"></p>';
 if(v.status==='recovery')return head+'<h1 id="cw-title" tabindex="-1">Earlier clock-walk work is kept</h1><p>This notebook cannot be opened here. Its complete original stays in your download.</p>'+btn('Start a separate clock-walk notebook','data-cw-recover')+status+'<a class="secondary" href="#notes">Download notes</a></section>';
 if(!v.work)return head+'<h1 id="cw-title" tabindex="-1">Courier Clock Walk</h1><p>A clock reading tells when. Elapsed minutes tell how long.</p>'+chooser(v)+status+'<a class="secondary" href="#notes">Download notes</a>'+(v.unreadable.length?btn('Start a separate clock-walk notebook','data-cw-recover'):'')+'</section>';
 const w=v.work,s=w.source;let body='';
 if(w.page==='learn')body=`<p>${esc(s.copy.idea)}</p><p>${esc(s.copy.scale)}</p><div class="cw-example" data-cw-example><div data-cw-example-model data-step="0">${example(w,0)}</div><div class="cw-actions">${[0,1,2].map(i=>btn('Example step '+(i+1),`data-cw-example-step="${i}" aria-pressed="${i===0}"`)).join('')}</div>${hearButton(s.example.captions[0],'Hear this example step').replace('<button ','<button data-cw-example-hear ')}</div>${btn('Go to our clock walk','data-cw-page="walk"',true)}`;
 if(w.page==='walk')body=`<p>${esc(s.copy.walkIdea)}</p><p>${esc(s.copy.instruction)}</p>${currentFigure(w)}<div class="cw-steps">${[[-15,'Back 15 minutes'],[-5,'Back 5 minutes'],[5,'Forward 5 minutes'],[15,'Forward 15 minutes']].map(([d,l])=>btn(l,`data-cw-step="${d}" ${w.offset+d<0||w.offset+d>60?'disabled':''}`)).join('')}</div><p class="tiny">${esc(endpoint(w))}.</p><div class="cw-actions">${btn('Use this model as our arrival','data-cw-endpoint="clock"')}${btn('Not sure about the arrival','data-cw-endpoint="unsure"')}</div><label for="cw-minutes">${esc(s.copy.durationPrompt)}</label><div class="cw-input"><input id="cw-minutes" type="text" inputmode="numeric" autocomplete="off" value="${esc(w.durationInput)}" aria-describedby="cw-minutes-status"><span>minutes</span></div><p id="cw-minutes-status" role="status" class="tiny">${w.durationMode==='unsure'?'Not sure about the minutes is selected.':'The minutes describe the card’s two supplied times.'}</p><div class="cw-actions">${btn('Not sure about the minutes','data-cw-unsure')}${btn('Leave minutes blank','data-cw-blank')}</div>${v.readableChecks.length>=4?`<p class="tiny">Checking now removes ${v.readableChecks.length-3} older readable check(s), leaving four recent checks. Our kept copy stays. Download first for a longer record.</p>`:''}${btn('Check our clock walk','data-cw-check',true)}${v.feedback?checkRecord(v.feedback,true):'<p>No check of this exact version is showing.</p>'}`;
 if(w.page==='kept')body=v.kept?'<h2>Our kept version</h2>'+reference(v.kept.snapshot.source)+`<p>Kept model: ${esc(label(v.kept.snapshot))}; ${v.kept.snapshot.offset} minutes from departure. Arrival: ${esc(endpoint(v.kept.snapshot))}. Proposed minutes: ${esc(answer(v.kept.snapshot))}.</p>`+(v.kept.check?checkRecord(v.kept.check):'<p>This version was kept without a check.</p>'):v.keptUnreadable?'<p>An earlier kept copy is unreadable and stays unchanged in your download. Start a separate clock-walk notebook to keep another copy.</p>':'<p>Nothing kept yet. Unfinished work is welcome.</p>';
 if(w.page==='kept')body+=v.feedback?'<details><summary>Check of our current draft</summary>'+checkRecord(v.feedback,true)+'</details>':'<p>No check of this exact current draft is showing.</p>';
 return head+`<p class="cw-eyebrow">Courier Clock Walk · ${pages.indexOf(w.page)+1} of 3</p><h1 id="cw-title" tabindex="-1">${({learn:'Learn about elapsed minutes',walk:'Walk between two times',kept:'Our kept clock walk'})[w.page]}</h1>${reference(s)}${hearButton(narration(v),'Hear this turn').replace('<button ','<button data-cw-hear ')}${status}${body}<nav class="cw-actions" aria-label="Clock walk turns">${pages.map(p=>btn(names[p],`data-cw-page="${p}" aria-current="${w.page===p?'page':'false'}"`)).join('')}</nav>${btn(w.kept===null?'Keep this version':'Replace our kept version',`data-cw-keep ${v.keptUnreadable?'disabled':''}`)}<details class="cw-extras"><summary>Help, earlier work and other cards</summary><p>${esc(s.story)}</p><p>${esc(s.copy.window)}</p><details class="cw-help"><summary>Help with elapsed minutes</summary><p>${esc(s.copy.help)}</p>${hearButton(s.copy.help,'Hear this explanation')}</details><details class="cw-departure"><summary>Departure clock picture</summary>${walkClock(s.departureMinute,'Fixed departure clock')}<p>Departure stays ${esc(s.departureLabel)}.</p></details>${btn('We thought together','data-cw-together')}<details><summary>Earlier checks (${v.readableChecks.length})</summary>${v.readableChecks.slice(-4).map(c=>checkRecord(c)).join('')}${v.rawChecks.length?'<p>Unreadable earlier checks remain in your download.</p>':''}</details>${chooser(v)}<details><summary>Grown-ups: practice and recovery</summary><p>Supplied labels and model intervals can reveal the answer. No independent reading, elapsed-time fluency or placement is inferred. Full source and raw work stay in the notes file.</p><a class="secondary" href="#notes">Download notes</a><a class="secondary" href="#workshop/clock">Preparation Clock</a>${btn('Start a separate clock-walk notebook','data-cw-recover')}</details></details></section>`;
}
export function clockWalkNotes(state){const v=clockWalkView(state);if(v.status==='missing')return '';if(v.status==='recovery')return '<section><h2>Courier Clock Walk</h2><p>Earlier raw notebook retained in this download.</p></section>';return `<details class="panel"><summary>Courier Clock Walk (${v.readable.length} cards)</summary><p>Supplied five-minute models and labels; practice only, prior exposure unknown. No independent clock reading or full elapsed-time proficiency is inferred.</p>${v.readable.map(c=>`<section><h3>${esc(c.work.source.title)}</h3>${reference(c.work.source)}<p>Current model ${esc(label(c.work))}; offset ${c.work.offset} minutes. Arrival: ${esc(endpoint(c.work))}. Proposed minutes: ${esc(answer(c.work))}. Support: ${esc(c.work.support.join(', ')||'none requested')}.</p>${c.readableChecks.slice(-4).map(x=>checkRecord(x)).join('')}${c.kept?`<p>Kept model ${esc(label(c.kept.snapshot))}; proposed minutes ${esc(answer(c.kept.snapshot))}.</p>`+(c.kept.check?checkRecord(c.kept.check):''):''}${c.rawChecks.length||c.keptUnreadable?'<p>Unreadable earlier work remains unchanged in this download.</p>':''}</section>`).join('')}${v.unreadable.length?'<p>Unreadable cards remain raw while readable cards stay open.</p>':''}</details>`;}
export function bindClockWalk(state,{save,render,focus,canExport}){
 const scope=document.querySelector('[data-cw-root]');if(!scope)return;const bound=clockWalkView(state).root?.current??null,live=b=>scope.isConnected&&b.isConnected&&scope.contains(b)&&(clockWalkView(state).root?.current??null)===bound;
 const message=t=>{const n=scope.querySelector('#cw-status');if(n)n.textContent=t;};
 const refusal='This change could not fit safely. Earlier work stays unchanged. Download notes, or use a separate explorer if the notebook is full.';
 const run=(fn,target)=>{if(!live(scope))return false;if(!fn()){message(refusal);return false;}save();render();if(target)focus(target);return true;};
 const bind=(selector,fn)=>scope.querySelectorAll(selector).forEach(b=>b.addEventListener('click',e=>{if(live(b))fn(b,e);}));
 const supplied=(kind,e)=>{if(!live(scope))return false;if(!supportClockWalk(state,kind,canExport)){message(refusal);e?.stopImmediatePropagation();return false;}save();if(!clockWalkView(state).feedback)scope.querySelectorAll('[data-cw-current]').forEach(c=>{c.removeAttribute('data-cw-current');c.querySelector('h3').textContent='Earlier recorded check '+c.dataset.cwRecord;});return true;};
 const confirm=(recovery,fn)=>{const d=document.createElement('dialog');d.innerHTML=`<div class="dialog-content"><h2>${recovery?'Start a separate clock-walk notebook?':'Replace our kept version?'}</h2><p>${recovery?'The entire earlier notebook, including kept and raw work, stays in your download.':'This overwrites the one earlier kept version for this card.'} Download notes first if you want another copy.</p><button class="secondary" data-cw-cancel>Keep this page</button><button class="primary" data-cw-confirm>Yes, continue</button></div>`;document.body.append(d);d.showModal();d.querySelector('[data-cw-cancel]').onclick=()=>d.close();d.querySelector('[data-cw-confirm]').onclick=()=>{if(!d.isConnected||!d.open||!live(scope))return;d.close();run(fn,'#cw-title');};d.addEventListener('close',()=>d.remove());};
 bind('[data-cw-start]',b=>run(()=>startClockWalk(state,b.dataset.cwStart,canExport),'#cw-title'));
 bind('[data-cw-page]',b=>run(()=>editClockWalk(state,'page',b.dataset.cwPage,canExport),'#cw-title'));
 bind('[data-cw-step]',b=>{const d=Number(b.dataset.cwStep);if(run(()=>editClockWalk(state,'step',d,canExport))){const selector=`[data-cw-step="${d}"]`,reverse=`[data-cw-step="${-d}"]`;focus(document.querySelector(selector)?.disabled?reverse:selector);}});
 bind('[data-cw-endpoint]',b=>run(()=>editClockWalk(state,'endpoint',b.dataset.cwEndpoint,canExport),`[data-cw-endpoint="${b.dataset.cwEndpoint}"]`));
 const input=scope.querySelector('#cw-minutes');input?.addEventListener('input',()=>{if(!live(input))return;const before=clockWalkView(state).work;if(!editClockWalk(state,'input',input.value,canExport)){input.value=before.durationInput;message(refusal);return;}save();scope.querySelector('#cw-minutes-status').textContent='The minutes describe the card’s two supplied times.';scope.querySelectorAll('[data-cw-current]').forEach(c=>{c.removeAttribute('data-cw-current');c.querySelector('h3').textContent='Earlier recorded check '+c.dataset.cwRecord;});});
 bind('[data-cw-unsure]',()=>run(()=>editClockWalk(state,'durationMode','unsure',canExport),'[data-cw-unsure]'));
 bind('[data-cw-blank]',()=>run(()=>editClockWalk(state,'input','',canExport),'#cw-minutes'));
 bind('[data-cw-check]',()=>{const w=clockWalkView(state).work;if(w.durationMode==='input'&&parseWalkMinutes(w.durationInput).kind==='invalid'){message('Use a whole number from 0 to 60, leave it blank, or choose Not sure. Your draft stays open.');focus('#cw-minutes');return;}if(run(()=>checkClockWalk(state,canExport)))focus('#cw-check-'+clockWalkView(state).feedback.id);});
 bind('[data-cw-keep]',()=>{const v=clockWalkView(state);if(v.keptUnreadable)return;if(v.work.kept!==null)confirm(false,()=>keepClockWalk(state,true,canExport));else if(run(()=>keepClockWalk(state,false,canExport))){document.querySelector('#cw-status').textContent='This version is kept.';focus('#cw-status');}});
 bind('[data-cw-recover]',()=>confirm(true,()=>recoverClockWalk(state,canExport)));
 bind('[data-cw-together]',(_b,e)=>{if(supplied('together',e))message('Thinking together is recorded.');});
 for(const [selector,kind]of [['.cw-help','help'],['.cw-departure','departurePicture']])scope.querySelector(selector)?.addEventListener('toggle',e=>{if(e.target.open&&!supplied(kind,e))e.target.open=false;});
 bind('[data-cw-example-step]',(b,e)=>{if(!supplied('example',e))return;const step=Number(b.dataset.cwExampleStep),w=clockWalkView(state).work,model=scope.querySelector('[data-cw-example-model]');model.innerHTML=example(w,step);model.dataset.step=String(step);scope.querySelector('[data-cw-example-hear]').dataset.speak=w.source.example.captions[step];scope.querySelectorAll('[data-cw-example-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));message('Example step '+(step+1)+'. Your own model stays unchanged.');});
 scope.querySelectorAll('[data-speak]').forEach(b=>b.addEventListener('click',e=>{if(!live(b)){e.stopImmediatePropagation();return;}if(b.hasAttribute('data-cw-hear'))b.dataset.speak=narration(clockWalkView(state));if(b.hasAttribute('data-cw-example-hear')){if(!supplied('example',e))return;}supplied('narrationRequested',e);}));
}
